import sympy as sp
import subprocess

class System:

    def __init__(self, A, b, label):
        self.A = A
        self.b = b
        self.label = label


def print_augmented_matrix(A, string):
    m, n = A.shape
    cols = "c" * (n - 1)
    cols += "|c"
    string += f"    & \\left( \\begin{{array}}{{{cols}}} \n"
    for i in range(m):
        string += "        "
        for j in range(n - 1):
            string += f" {sp.latex(A[i,j])} &"
        string += f" {sp.latex(A[i,-1])} \\\ \n"
    string += "    \\end{array} \\right) \n"

    return string


def gelim(A, string):
    m, n = A.shape

    string += "\n$$ \\begin{align*} \n"
    string = print_augmented_matrix(A, string)
    andflag = True

    pivotrow = 0
    for j in range(n):

        if pivotrow == m - 1:
            break 

        # Swap pivot row if pivot is zero
        if A[pivotrow,j] == 0:  
            for i in range(pivotrow, m):
                if A[i,j] != 0:
                    break

            string += "\\begin{array}{l} "
            for k in range(m):
                if k == pivotrow:
                    string += f"R_{{pivotrow}} \\leftrightarrow R_{{i}} \\\ "
                else:
                    string += "\\phantom{x} "

            if andflag and n < 5:
                string += "\\end{array} & \n"
                andflag = False
            else:
                string += "\\end{array} \\\ \\\ \n"
                andflag = True

            continue

        # Row reduce rows below pivot row 
        if pivotrow < m - 1:
            string += "    \\begin{array}{l} "
            for i in range(m):
                scalar = A[i,j] / A[pivotrow,j]
                if i <= pivotrow:
                    string += "\\phantom{x} "
                elif scalar == 1:
                    string += f"R_{{{i+1}}} - R_{{{pivotrow+1}}} "
                elif scalar == -1:
                    string += f"R_{{{i+1}}} + R_{{{pivotrow+1}}} "
                elif scalar > 0:
                    string += f"R_{{{i+1}}} - {sp.latex(abs(scalar))} R_{{{pivotrow+1}}} "
                elif scalar < 0:
                    string += f"R_{{{i+1}}} + {sp.latex(abs(scalar))} R_{{{pivotrow+1}}}"
                else:
                    string += "\\phantom{x} "

                if i < m - 1:
                    string += "\\\ "

                if i <= pivotrow:
                    continue

                A[i,:] -= scalar * A[pivotrow,:]

            if andflag and n < 5:
                string += "\\end{array} & \n"
                andflag = False
            else:
                string += "\\end{array} \\\ \\\ \n"
                andflag = True

        # Print updated matrix
        string += "    \\longrightarrow \n"
        string = print_augmented_matrix(A, string)
        pivotrow += 1

    string += "\\end{align*} $$ \n"

    return A, string



def back_substitution(A, string):
    m, n = A.shape
    x = A[:,-1]
    string += "\nSolving by back substitution gives\n\n"
    string += "$$ \\begin{align*} \n"

    for i in range(m - 1, -1, -1):
        string += f"    x_{{{i+1}}} &= "
        if A[i,i] == 1:
            string += f"{sp.latex(A[i,-1])}"
        elif A[i,i] == -1:
            string += f" - \\left( {sp.latex(A[i,-1])}"
        elif A[i,i] < 0:
            string += f" - \\frac{{1}}{{{sp.latex(-A[i,i])}}} \\left( {sp.latex(A[i,-1])}"
        else:
            string += f" \\frac{{1}}{{{sp.latex(A[i,i])}}} \\left( {sp.latex(A[i,-1])}"

        for j in range(i + 1, n - 1):
            if A[i,j] >= 0:
                string += f" - {sp.latex(A[i,j])} \\left( {sp.latex(x[j])} \\right)"
            else:
                string += f" - \\left( {sp.latex(A[i,j])} \\right) \\left( {sp.latex(x[j])} \\right)"
            x[i] -= A[i,j] * x[j]

        x[i] /= A[i,i]

        if A[i,i] == 1:
            string += " = "
        else:
            string += " \\right) = "
        string += f"{sp.latex(x[i])}"

        if i > 0:
            string += ", \\\ \n"
        else:
            string += ". \n"

    string += "\\end{align*} $$ \n"

    return string


