systems.append(System(sp.Matrix([[3, -5, -4, -1], [0, -4, 3, -4], [2, 3, 3, -3], [-2, 2, -5, -4]]), sp.Matrix([[28], [41], [11], [-21]]), "(e)"))
systems.append(System(sp.Matrix([[2, -3, -3, 4], [4, -5, 1, -5], [3, 3, -1, -5], [1, 0, 1, 3]]), sp.Matrix([[-1], [42], [20], [-4]]), "(f)"))

